css:
.sti { font-family: "Inter", -apple-system, "Segoe UI", sans-serif; color: #1e293b; font-size: 13px; }
.sti-head { display: flex; justify-content: space-between; gap: 24px; padding-bottom: 16px; border-bottom: 2px solid #4f46e5; }
.sti-vendor { font-size: 20px; font-weight: 700; color: #312e81; margin-bottom: 4px; }
.sti-title { font-size: 20px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: #4f46e5; text-align: right; }
.sti-right { text-align: right; }
.sti-meta { margin-left: auto; margin-top: 8px; }
.sti-meta td { padding: 2px 0 2px 16px; text-align: right; }
.sti-muted { color: #64748b; }
.sti-label { font-size: 11px; font-weight: 700; text-transform: uppercase; color: #94a3b8; margin-bottom: 4px; }
.sti-strong { font-weight: 600; font-size: 15px; }
.sti-bill { margin: 20px 0; padding: 14px 16px; background: #f8fafc; border-radius: 8px; }
.sti-items, .sti-totals { width: 100%; border-collapse: collapse; }
.sti-items th { text-align: left; font-size: 11px; text-transform: uppercase; color: #64748b; border-bottom: 1px solid #cbd5e1; padding: 8px 6px; }
.sti-items td { padding: 10px 6px; border-bottom: 1px solid #e2e8f0; vertical-align: top; }
.sti .num { text-align: right; white-space: nowrap; }
.sti-totals { width: 50%; margin-left: auto; margin-top: 12px; }
.sti-totals td { padding: 5px 6px; }
.sti-grand td { font-weight: 700; font-size: 15px; border-top: 2px solid #1e293b; padding-top: 8px; }
.sti-words { text-align: right; margin-top: 6px; color: #475569; font-style: italic; }
.sti-foot { margin-top: 32px; padding-top: 12px; border-top: 1px solid #e2e8f0; display: grid; gap: 6px; }
